mapper.select:
SELECT t.id, t.ticket_no, t.title, t.category_id, t.priority, t.status,
t.requester_id, t.assignee_id, t.respond_deadline, t.resolve_deadline,
t.create_time, t.update_time,
c.name AS category_name,
ru.name AS requester_name,
au.name AS assignee_name
FROM ticket t
LEFT JOIN ticket_category c ON c.id = t.category_id AND c.deleted = 0
LEFT JOIN sys_user ru ON ru.id = t.requester_id
LEFT JOIN sys_user au ON au.id = t.assignee_id

    t.deleted = 0
    AND t.status = #{status}
    AND t.priority = #{priority}
    AND t.category_id = #{categoryId}
    AND t.channel = #{channel}
    AND t.requester_id = #{requesterId}
    AND t.assignee_id = #{assigneeId}

        AND (t.title LIKE CONCAT('%', #{keyword}, '%')
        OR t.ticket_no LIKE CONCAT('%', #{keyword}, '%')
        OR t.content LIKE CONCAT('%', #{keyword}, '%'))

    AND t.create_time >= #{createTimeStart}
    AND t.create_time <= #{createTimeEnd}


ORDER BY t.priority ASC, t.create_time DESC
